        },
        {
          id: 4,
          status: "success",
          title: "文档更新完成",
          agent: "docs-gen",
          project: "anotify",
          duration: 58,
          model: "claude-4",
          time: "3 小时前",
          body: "生成 3 个页面：README、API 参考、部署指南。",
          link: "pi://session/sess_77aa",
          sessionId: "sess_77aa09",
          delivered: 4,
          total: 4,
        },
        {
          id: 5,
          status: "success",
          title: "代码审查完成",
          agent: "reviewer",
          project: "auth-module",
          duration: 91,
          model: "claude-4",
          time: "5 小时前",
          body: "审查了 12 个文件，发现 2 个潜在空指针，已生成修复建议。",
          link: "pi://session/sess_31de",
          sessionId: "sess_31de4b",
          delivered: 4,
          total: 4,
        },
        {
          id: 6,
          status: "error",
          title: "数据库迁移失败",
          agent: "db-migrate",
          project: "core-db",
          duration: 47,
          model: "claude-4",
          time: "昨天 23:41",
          body: "迁移脚本 0042 执行超时。已自动回滚，数据未受影响。",
          link: "pi://session/sess_5f2c",
